def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    grid = input_data[1:]

    D = [[-1] * n for _ in range(n)]
    D_prime = [[[-1] * 26 for _ in range(n)] for _ in range(n)]

    q = deque()

    out_edges = [[[] for _ in range(26)] for _ in range(n)]
    in_edges = [[] for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if grid[i][j] != '-':
                c = ord(grid[i][j]) - ord('a')
                out_edges[i][c].append(j)
                in_edges[j].append((i, c))

    for i in range(n):
        D[i][i] = 0
        q.append((0, i, i, -1))

    for i in range(n):
        for j in range(n):
            if grid[i][j] != '-':
                if D[i][j] == -1:
                    D[i][j] = 1
                    q.append((0, i, j, -1))

    while q:
        state = q.popleft()
        type_ = state[0]

        if type_ == 0:
            u = state[1]
            v = state[2]
            d = D[u][v]

            for x, c in in_edges[u]:
                if D_prime[x][v][c] == -1:
                    D_prime[x][v][c] = d + 1
                    q.append((1, x, v, c))
        else:
            x = state[1]
            v = state[2]
            c = state[3]
            d = D_prime[x][v][c]

            for y in out_edges[v][c]:
                if D[x][y] == -1:
                    D[x][y] = d + 1
                    q.append((0, x, y, -1))

    out_lines = []
    for i in range(n):
        out_lines.append(" ".join(map(str, D[i])))
    sys.stdout.write("\n".join(out_lines) + "\n")

if __name__ == '__main__':
    solve()

